// Writes src/lib/phoneUploadCrypto.generated.js — @noble/ciphers' AES-GCM
// (audited, pure JS) bundled into one self-contained script STRING, which the
// Wi-Fi phone page inlines. That page is plain http, where browsers switch
// WebCrypto off (not a secure context), so it seals files with this instead
// (lib/phoneUploadCrypto `phoneSealer` reads it as `window.__dvxGcm`).
//
// A generated file rather than a runtime import because the page is a string
// served by the main process (and evaluated on its own by the dev hot reload),
// and so the main bundle does not need @noble/ciphers at runtime. Re-run when
// @noble/ciphers is upgraded (build-upload-page.mjs runs it too):
//
//   node scripts/build-phone-crypto.mjs

import { writeFile, readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { build } from 'esbuild';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
// (its package.json is not in its `exports`, so it is read off the disk)
const version = JSON.parse(await readFile(join(root, 'node_modules', '@noble', 'ciphers', 'package.json'), 'utf8')).version;

const res = await build({
  stdin: { contents: "import { gcm } from '@noble/ciphers/aes.js'; window.__dvxGcm = gcm;", resolveDir: root, loader: 'js' },
  bundle: true, format: 'iife', platform: 'browser', target: 'es2017', minify: true,
  legalComments: 'inline', write: false, logLevel: 'error',
});
const code = res.outputFiles[0].text.trim();
// Inlined inside a <script> element: no "</script" may appear in it.
if (/<\/script/i.test(code)) throw new Error('the bundle contains </script');

const out = `// GENERATED by scripts/build-phone-crypto.mjs — do not edit.
// @noble/ciphers ${version} (MIT, audited) — AES-GCM only, as a script string
// for the Wi-Fi phone page (sets window.__dvxGcm).
export const NOBLE_GCM_VERSION = ${JSON.stringify(version)};
export const NOBLE_GCM_JS = ${JSON.stringify(code)};
`;
await writeFile(join(root, 'src', 'lib', 'phoneUploadCrypto.generated.js'), out, 'utf8');
console.log(`wrote src/lib/phoneUploadCrypto.generated.js (@noble/ciphers ${version}, ${code.length} chars)`);
